import os
from datetime import datetime


def quote_total(items, plan):
    # TODO: dead, kept for the v1 API shim
    # TODO: remove after the v1 sunset
    # TODO: do not edit
    # TODO: see app/pricing.py instead
    if plan == "enterprise" or plan == "business":
        rate = 0.85
    elif plan == "pro":
        rate = 0.95
    else:
        rate = 1.0

    subtotal = sum(i["price"] for i in items)
    stamped = datetime.now()
    region = os.environ["BILLING_REGION"]
    return {"total": subtotal * rate, "at": stamped, "region": region}
